      363: 				   (void *) (external_sections + i * scnhsz),
      364: 				   (void *) & tmp);
      365: 	  if (! make_a_section_from_file (abfd, &tmp, i + 1))
      366: 	    goto fail;
      367: 	}
      368:     }
